/// `Statement::is_allowed`.
pub fn statement_is_allowed(st: &Statement, args: &Args, env: &Env) -> bool {
    let ctx = Some(resolver_for(args, env));
    let check = reaches_condition_eval(st, args, &ctx) && functions_evaluate(&st.conditions, &args.conditions, &ctx, env);
    effect_is_allowed(st.effect, check)
}

/// `Policy::is_allowed`: any matching Deny refuses; then `deny_only` or
/// ownership allow; then an Allow must match.
pub fn policy_is_allowed(statements: &[Statement], args: &Args, env: &Env) -> bool {
    if !denies_pass(statements, args, env) {
        return false;
    }
    if args.deny_only {
        return true;
    }
    if args.is_owner {
        return true;
    }
    some_allow(statements, args, env)
}

/// `Effect::is_allowed`.
pub fn effect_is_allowed(e: Effect, allowed: bool) -> bool {
    match e {
        Effect::Allow => allowed,
        Effect::Deny => !allowed,
    }
}

fn some_allow(sts: &[Statement], args: &Args, env: &Env) -> bool {
    let mut i = 0;
    while i < sts.len() {
        if sts[i].effect == Effect::Allow && statement_is_allowed(&sts[i], args, env) {
            return true;
        }
        i += 1;
    }
    false
}

